function merge(intervals) {
  intervals.sort((a, b) => a[0] - b[0]);          // 1. sort by start
  const merged = [[...intervals[0]]];
  for (let i = 1; i < intervals.length; i++) {
    const last = merged[merged.length - 1];
    const [start, end] = intervals[i];
    if (start <= last[1]) {
      last[1] = Math.max(last[1], end);           // overlap: extend
    } else {
      merged.push([start, end]);                  // gap: start a new one
    }
  }
  return merged;
}

def merge(intervals):
    intervals.sort(key=lambda it: it[0])          # 1. sort by start
    merged = [list(intervals[0])]
    for start, end in intervals[1:]:
        last = merged[-1]
        if start <= last[1]:
            last[1] = max(last[1], end)           # overlap: extend
        else:
            merged.append([start, end])           # gap: start a new one
    return merged

class Solution {
    public int[][] merge(int[][] intervals) {
        Arrays.sort(intervals, (a, b) -> Integer.compare(a[0], b[0]));   // 1. sort by start
        List<int[]> merged = new ArrayList<>();
        merged.add(intervals[0].clone());
        for (int i = 1; i < intervals.length; i++) {
            int[] last = merged.get(merged.size() - 1);
            if (intervals[i][0] <= last[1]) {
                last[1] = Math.max(last[1], intervals[i][1]);            // overlap: extend
            } else {
                merged.add(intervals[i].clone());                        // gap: start a new one
            }
        }
        return merged.toArray(new int[0][]);
    }
}

class Solution {
public:
    vector<vector<int>> merge(vector<vector<int>>& intervals) {
        sort(intervals.begin(), intervals.end());          // 1. sort by start
        vector<vector<int>> merged = {intervals[0]};
        for (size_t i = 1; i < intervals.size(); i++) {
            vector<int>& last = merged.back();
            if (intervals[i][0] <= last[1]) {
                last[1] = max(last[1], intervals[i][1]);   // overlap: extend
            } else {
                merged.push_back(intervals[i]);            // gap: start a new one
            }
        }
        return merged;
    }
};
